// vc patch: st-run/node_modules is a symlink to the locked install outside serverDirectory.
// Node realpaths import.meta.url, so WASM codecs fetch that real file:// path.
// Allow only that realpath plus serverDirectory. The .wasm allowlist still applies.
function isAllowedFileRoot(filePath) {
    if (isPathUnderParent(serverDirectory, filePath)) return true;
    let realModules;
    try {
        realModules = fs.realpathSync(path.join(serverDirectory, 'node_modules'));
    } catch {
        return false;
    }
    if (realModules === path.parse(realModules).root) return false;
    return isPathUnderParent(realModules, filePath);
}

// Patched fetch function that handles file URLs.
globalThis.fetch = async
